/* Minimal Papa.parse-compatible local CSV reader for the episode viewer. */
(function (global) {
  "use strict";

  function rowsFromCsv(text) {
    const rows = [];
    let row = [];
    let field = "";
    let quoted = false;
    for (let index = 0; index < text.length; index += 1) {
      const character = text[index];
      if (quoted) {
        if (character === '"' && text[index + 1] === '"') {
          field += '"';
          index += 1;
        } else if (character === '"') {
          quoted = false;
        } else {
          field += character;
        }
      } else if (character === '"' && field === "") {
        quoted = true;
      } else if (character === ",") {
        row.push(field);
        field = "";
      } else if (character === "\n") {
        row.push(field.endsWith("\r") ? field.slice(0, -1) : field);
        rows.push(row);
        row = [];
        field = "";
      } else {
        field += character;
      }
    }
    if (field !== "" || row.length) {
      row.push(field.endsWith("\r") ? field.slice(0, -1) : field);
      rows.push(row);
    }
    return { rows, unclosedQuote: quoted };
  }

  function typed(value, enabled) {
    if (!enabled) return value;
    const trimmed = value.trim();
    if (trimmed === "") return null;
    if (/^(?:true|false)$/i.test(trimmed)) return trimmed.toLowerCase() === "true";
    const number = Number(trimmed);
    return Number.isFinite(number) ? number : value;
  }

  global.Papa = {
    parse(file, options) {
      file.text().then(text => {
        const parsed = rowsFromCsv(text.replace(/^\uFEFF/, ""));
        const rawRows = options.skipEmptyLines
          ? parsed.rows.filter(row => row.some(field => field.trim() !== ""))
          : parsed.rows;
        const fields = rawRows.shift() || [];
        const errors = [];
        if (parsed.unclosedQuote) errors.push({ code: "MissingQuotes", message: "Unclosed quoted field" });
        const data = rawRows.map((values, rowIndex) => {
          if (values.length !== fields.length) {
            errors.push({ code: "FieldMismatch", row: rowIndex, message: `Expected ${fields.length} fields, got ${values.length}` });
          }
          return Object.fromEntries(fields.map((field, index) => [field, typed(values[index] || "", options.dynamicTyping)]));
        });
        options.complete({ data, errors, meta: { fields } });
      }).catch(error => options.error(error));
    }
  };
})(window);
